import {
  Box,
} from "@mui/material";

import WeatherIntelligence from "./WeatherIntelligence";
import ForecastStatistics from "./ForecastStatistics";
import ForecastTrendChart from "./ForecastTrendChart";
import StockpileTrajectory from "./StockpileTrajectory";
import ForecastInsights from "./ForecastInsights";
import ScenarioComparison from "./ScenarioComparison";
import ForecastResults from "./ForecastResults";

import {
  useForecastContext,
} from "../../../contexts/ForecastContext";

import {
  ForecastFilters,
} from "../types/forecast.types";


const ForecastOverview = () => {
  const {
    horizon,
    metric,
    entityId,
    scenario,
  } =
    useForecastContext();


  const filters:
    ForecastFilters = {
      horizon,
      metric,
      entityId,
      scenario,
    };


  return (
    <Box
      sx={{
        width: "100%",
        minWidth: 0,
      }}
    >




      {/* ==================================================
          FORECAST STATISTICS
      ================================================== */}

      <Box
        sx={{
          width: "100%",
          minWidth: 0,
          mb: {
            xs: 2.5,
            md: 3,
          },
        }}
      >
        <ForecastStatistics />
      </Box>

            {/* ==================================================
          WEATHER INTELLIGENCE
      ================================================== */}

      <Box
        sx={{
          width: "100%",
          minWidth: 0,
          mb: {
            xs: 2.5,
            md: 3,
          },
        }}
      >
        <WeatherIntelligence
          entityId={entityId}
        />
      </Box>


      {/* ==================================================
          MAIN FORECAST TREND
      ================================================== */}

      <Box
        sx={{
          width: "100%",
          minWidth: 0,
          mb: {
            xs: 2.5,
            md: 3,
          },

          "& > *": {
            width: "100%",
            minWidth: 0,
          },
        }}
      >
        <ForecastTrendChart
          filters={filters}
        />
      </Box>


      {/* ==================================================
          STOCKPILE + INSIGHTS
      ================================================== */}

      <Box
        sx={{
          width: "100%",
          minWidth: 0,

          display: "grid",

          gridTemplateColumns: {
            xs:
              "minmax(0, 1fr)",

            xl:
              "minmax(0, 1.35fr) minmax(0, 1fr)",
          },

          gap: {
            xs: 2.5,
            md: 3,
          },

          alignItems:
            "stretch",

          mb: {
            xs: 2.5,
            md: 3,
          },

          "& > *": {
            minWidth: 0,
          },
        }}
      >

        <Box
          sx={{
            minWidth: 0,
            width: "100%",
          }}
        >
          <StockpileTrajectory
            filters={
              filters
            }
          />
        </Box>


        <Box
          sx={{
            minWidth: 0,
            width: "100%",
          }}
        >
          <ForecastInsights
            filters={
              filters
            }
          />
        </Box>

      </Box>


      {/* ==================================================
          SCENARIO COMPARISON
      ================================================== */}

      <Box
        sx={{
          width: "100%",
          minWidth: 0,
          mb: {
            xs: 2.5,
            md: 3,
          },

          "& > *": {
            width: "100%",
            minWidth: 0,
          },
        }}
      >
        <ScenarioComparison
          filters={
            filters
          }
        />
      </Box>


      {/* ==================================================
          FORECAST RESULTS
      ================================================== */}

      {/* <Box
        sx={{
          width: "100%",
          minWidth: 0,

          "& > *": {
            width: "100%",
            minWidth: 0,
          },
        }}
      >
        <ForecastResults
          filters={
            filters
          }
        />
      </Box> */}

    </Box>
  );
};


export default ForecastOverview;
